WITH valid AS (SELECT *, UPPER(country) AS country_upper, COALESCE(city, 'NONE') AS city_clean FROM suppliers WHERE city IS NOT NULL) SELECT id, country, country_upper, city_clean, COUNT(rating) OVER w_hist AS running_count_rating, AVG(rating) OVER w_hist AS running_avg_rating, SUM(rating) OVER w_hist AS running_sum_rating, SUM(rating) OVER w_hist AS running_rating FROM valid WINDOW w_hist AS (PARTITION BY country, city ORDER BY rating, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
